<style>
.admin-profile{max-width:1060px}.profile-banner{background:linear-gradient(135deg,#4f46e5,#7c83f5);height:150px;border-radius:20px 20px 0 0}.profile-wrap{margin-top:-65px;position:relative}.profile-avatar-lg{width:130px;height:130px;border-radius:50%;object-fit:cover;border:5px solid var(--card);box-shadow:0 10px 30px rgba(24,32,47,.16);background:#eef0ff;color:#4f46e5;display:grid;place-items:center;font-size:40px}.profile-camera{position:absolute;left:92px;bottom:3px;width:38px;height:38px;border:3px solid var(--card);border-radius:50%;background:#4f46e5;color:#fff;display:grid;place-items:center;cursor:pointer}.photo-action{display:none;margin-top:10px;border:0;border-radius:9px;padding:8px 15px;background:#4f46e5;color:#fff;font-size:12px;font-weight:700;cursor:pointer}.photo-action.show{display:inline-flex;align-items:center;gap:6px}.photo-action:disabled{opacity:.65;cursor:not-allowed}.profile-card2{background:var(--card);border:1px solid var(--border);border-radius:20px;box-shadow:0 10px 32px rgba(25,34,52,.05);overflow:hidden}.profile-body{padding:24px 28px 30px}.profile-name{font-size:24px;font-weight:800;margin-top:12px}.profile-sub{color:var(--muted);font-size:13px}.section-box{border-top:1px solid var(--border);margin-top:24px;padding-top:24px}.section-box h6{font-weight:750;margin-bottom:17px}.label-sm{font-size:11px;font-weight:700;color:var(--muted);margin-bottom:6px}.profile-form .form-control{height:44px}.save-profile{min-width:150px}.status-msg{min-height:20px;font-size:12px}@media(max-width:700px){.profile-banner{height:120px}.profile-body{padding:20px}.profile-avatar-lg{width:112px;height:112px}.profile-camera{left:78px}}
</style>
<div class="admin-profile"><div class="mb-4"><div class="page-heading">My profile</div><div class="page-subtitle">Manage your administrator account, profile photo and password.</div></div><div class="profile-card2"><div class="profile-banner"></div><div class="profile-body"><div class="profile-wrap"><div class="position-relative d-inline-block"><?php if(!empty($admin->image)): ?><img class="profile-avatar-lg" id="adminProfilePreview" src="<?= profile_image_url($admin->image, TRUE) ?>" alt="Profile photo" onerror="this.onerror=null;this.src='<?= base_url('assets/uploads/profile-placeholder.svg'); ?>';"><?php else: ?><div class="profile-avatar-lg" id="adminProfilePreview"><i class="fa-solid fa-user"></i></div><?php endif; ?><label class="profile-camera" for="adminProfileInput" title="Change profile photo"><i class="fa-solid fa-camera"></i></label><button type="button" class="photo-action" id="addAdminImageBtn"><i class="fa-solid fa-cloud-arrow-up"></i> Add Image</button><input type="file" id="adminProfileInput" name="profile_image" hidden accept="image/jpeg,image/png,image/webp"></div></div><div class="profile-name" id="adminProfileName"><?= html_escape(!empty($admin->name)?$admin->name:$admin->username) ?></div><div class="profile-sub"><?= html_escape($admin->email ?? '') ?> · Administrator</div><div id="photoStatus" class="status-msg mt-2"></div><form id="adminProfileForm" class="profile-form" enctype="multipart/form-data"><div id="profileAlert" class="alert rounded-3 mt-3" style="display:none"></div><div class="section-box"><h6><i class="fa-regular fa-id-card me-2 text-primary"></i>Account details</h6><div class="row g-3"><div class="col-md-6"><div class="label-sm">Name</div><input class="form-control" name="name" value="<?= html_escape($admin->name ?? $admin->username) ?>" required></div><div class="col-md-6"><div class="label-sm">Email</div><input class="form-control" type="email" name="email" value="<?= html_escape($admin->email ?? '') ?>" required></div></div></div><div class="section-box"><h6><i class="fa-solid fa-lock me-2 text-primary"></i>Change password</h6><div class="row g-3"><div class="col-md-4"><div class="label-sm">Current password</div><input class="form-control" type="password" name="current_password" autocomplete="current-password"></div><div class="col-md-4"><div class="label-sm">New password</div><input class="form-control" type="password" name="new_password" autocomplete="new-password"></div><div class="col-md-4"><div class="label-sm">Confirm new password</div><input class="form-control" type="password" name="confirm_password" autocomplete="new-password"></div></div><div class="text-muted mt-2" style="font-size:11px">Leave password fields blank when you only want to update your profile details.</div></div><div class="d-flex justify-content-end mt-4"><button class="btn btn-primary save-profile" id="saveAdminProfile" type="submit"><i class="fa-solid fa-check me-1"></i> Save changes</button></div></form></div></div></div>
<script>
document.addEventListener('DOMContentLoaded',function(){
 const input=document.getElementById('adminProfileInput'),addBtn=document.getElementById('addAdminImageBtn'),form=document.getElementById('adminProfileForm'),btn=document.getElementById('saveAdminProfile'),status=document.getElementById('photoStatus'),alertBox=document.getElementById('profileAlert');
 let selectedFile=null;
 function show(type,msg){alertBox.className='alert alert-'+type+' rounded-3';alertBox.style.display='block';alertBox.textContent=msg;}
 function cacheUrl(url){return url ? url+'?v='+Date.now() : '';}
 input.addEventListener('change',function(){const f=this.files[0];if(!f)return;if(f.size>2*1024*1024){status.innerHTML='<span class="text-danger">Image must be 2 MB or smaller.</span>';this.value='';addBtn.classList.remove('show');selectedFile=null;return;}if(!['image/jpeg','image/png','image/webp'].includes(f.type)){status.innerHTML='<span class="text-danger">Please select JPG, PNG or WEBP.</span>';this.value='';addBtn.classList.remove('show');selectedFile=null;return;}selectedFile=f;const url=URL.createObjectURL(f),old=document.getElementById('adminProfilePreview');if(old.tagName==='IMG'){old.src=url}else{const img=document.createElement('img');img.id='adminProfilePreview';img.className='profile-avatar-lg';img.src=url;img.alt='Profile photo';old.replaceWith(img);}addBtn.classList.add('show');status.innerHTML='<span class="text-muted">Image selected. Click <b>Add Image</b> to upload it.</span>';});
 addBtn.addEventListener('click',function(){if(!selectedFile)return;addBtn.disabled=true;addBtn.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i> Uploading...';const fd=new FormData();fd.append('profile_image',selectedFile);fetch('<?= site_url('admin/profile/upload_image') ?>',{method:'POST',body:fd,headers:{'X-Requested-With':'XMLHttpRequest'}}).then(r=>r.json()).then(d=>{if(d.status!=='success')throw new Error(d.message||'Upload failed');const url=cacheUrl(d.image_url);['adminNavImage','adminMenuImage','sidebarAdminImage'].forEach(function(id){const el=document.getElementById(id);if(el)el.src=url;});const preview=document.getElementById('adminProfilePreview');if(preview&&preview.tagName==='IMG')preview.src=url;status.innerHTML='<span class="text-success">Admin profile image added successfully.</span>';input.value='';selectedFile=null;addBtn.classList.remove('show');}).catch(e=>{status.innerHTML='<span class="text-danger">'+(e.message||'Unable to upload image.')+'</span>';}).finally(()=>{addBtn.disabled=false;addBtn.innerHTML='<i class="fa-solid fa-cloud-arrow-up"></i> Add Image';});});
 form.addEventListener('submit',function(e){e.preventDefault();btn.disabled=true;btn.innerHTML='<i class="fa-solid fa-spinner fa-spin me-1"></i> Saving...';fetch('<?= site_url('admin/profile/update') ?>',{method:'POST',body:new FormData(form),headers:{'X-Requested-With':'XMLHttpRequest'}}).then(r=>r.json()).then(d=>{show(d.status==='success'?'success':'danger',d.message||'Unable to update profile.');if(d.status==='success'){document.getElementById('adminProfileName').textContent=form.elements.name.value;const n=document.getElementById('adminMenuName');if(n)n.textContent=form.elements.name.value;if(d.image_url){const url=cacheUrl(d.image_url);['adminNavImage','adminMenuImage','sidebarAdminImage'].forEach(function(id){const el=document.getElementById(id);if(el)el.src=url;});const preview=document.getElementById('adminProfilePreview');if(preview&&preview.tagName==='IMG')preview.src=url;}form.elements.current_password.value='';form.elements.new_password.value='';form.elements.confirm_password.value='';status.innerHTML='<span class="text-success">Profile saved successfully.</span>';}}).catch(()=>show('danger','Unable to update profile.')).finally(()=>{btn.disabled=false;btn.innerHTML='<i class="fa-solid fa-check me-1"></i> Save changes'});});
});
</script>